"use strict";(self["webpackChunk"]=self["webpackChunk"]||[]).push([[1368],{421368(__unused_webpack_module,__webpack_exports__,__webpack_require__){__webpack_require__.r(__webpack_exports__);__webpack_require__.d(__webpack_exports__,{default:()=>__WEBPACK_DEFAULT_EXPORT__});const __WEBPACK_DEFAULT_EXPORT__='// SPDX-License-Identifier: MIT\npragma solidity ^0.8.20;\n\nimport "@openzeppelin/contracts/governance/Governor.sol";\nimport "@openzeppelin/contracts/governance/extensions/GovernorSettings.sol";\nimport "@openzeppelin/contracts/governance/extensions/GovernorCountingSimple.sol";\nimport "@openzeppelin/contracts/governance/extensions/GovernorVotes.sol";\nimport "@openzeppelin/contracts/governance/extensions/GovernorVotesQuorumFraction.sol";\nimport "@openzeppelin/contracts/governance/extensions/GovernorTimelockControl.sol";\n\n/**\n * @title DAOGovernor\n * @dev An OpenZeppelin Governor-style DAO with on-chain proposal execution.\n *\n * Governance flow:\n * 1. Token holders delegate voting power (self-delegate to activate)\n * 2. Propose: create an on-chain proposal (requires proposalThreshold voting power)\n * 3. Vote: token holders vote For/Against/Abstain during the voting period\n * 4. Queue: if quorum & majority met, queue in the Timelock\n * 5. Execute: after timelock delay, anyone can execute the proposal\n *\n * This pattern is used by: Uniswap, Compound, Aave, ENS, Gitcoin DAOs.\n */\ncontract DAOGovernor is\n    Governor,\n    GovernorSettings,\n    GovernorCountingSimple,\n    GovernorVotes,\n    GovernorVotesQuorumFraction,\n    GovernorTimelockControl\n{\n    constructor(\n        IVotes _token,\n        TimelockController _timelock\n    )\n        Governor("DAOGovernor")\n        GovernorSettings(\n            1,      // 1 block voting delay\n            50400,  // ~1 week voting period (at 12s/block)\n            0       // No minimum proposal threshold\n        )\n        GovernorVotes(_token)\n        GovernorVotesQuorumFraction(4) // 4% quorum\n        GovernorTimelockControl(_timelock)\n    {}\n\n    // Required overrides\n\n    function votingDelay() public view override(Governor, GovernorSettings) returns (uint256) {\n        return super.votingDelay();\n    }\n\n    function votingPeriod() public view override(Governor, GovernorSettings) returns (uint256) {\n        return super.votingPeriod();\n    }\n\n    function quorum(uint256 blockNumber)\n        public\n        view\n        override(Governor, GovernorVotesQuorumFraction)\n        returns (uint256)\n    {\n        return super.quorum(blockNumber);\n    }\n\n    function state(uint256 proposalId)\n        public\n        view\n        override(Governor, GovernorTimelockControl)\n        returns (ProposalState)\n    {\n        return super.state(proposalId);\n    }\n\n    function proposalNeedsQueuing(uint256 proposalId)\n        public\n        view\n        override(Governor, GovernorTimelockControl)\n        returns (bool)\n    {\n        return super.proposalNeedsQueuing(proposalId);\n    }\n\n    function proposalThreshold()\n        public\n        view\n        override(Governor, GovernorSettings)\n        returns (uint256)\n    {\n        return super.proposalThreshold();\n    }\n\n    function _queueOperations(\n        uint256 proposalId,\n        address[] memory targets,\n        uint256[] memory values,\n        bytes[] memory calldatas,\n        bytes32 descriptionHash\n    ) internal override(Governor, GovernorTimelockControl) returns (uint48) {\n        return super._queueOperations(proposalId, targets, values, calldatas, descriptionHash);\n    }\n\n    function _executeOperations(\n        uint256 proposalId,\n        address[] memory targets,\n        uint256[] memory values,\n        bytes[] memory calldatas,\n        bytes32 descriptionHash\n    ) internal override(Governor, GovernorTimelockControl) {\n        super._executeOperations(proposalId, targets, values, calldatas, descriptionHash);\n    }\n\n    function _cancel(\n        address[] memory targets,\n        uint256[] memory values,\n        bytes[] memory calldatas,\n        bytes32 descriptionHash\n    ) internal override(Governor, GovernorTimelockControl) returns (uint256) {\n        return super._cancel(targets, values, calldatas, descriptionHash);\n    }\n\n    function _executor()\n        internal\n        view\n        override(Governor, GovernorTimelockControl)\n        returns (address)\n    {\n        return super._executor();\n    }\n}\n'}}]);